type LRUCache struct {
	cap    int
	caches map[int]*Node
	left   *Node
	right  *Node
}
type Node struct {
	key  int
	val  int
	prev *Node
	next *Node
}
func Constructor(capacity int) LRUCache {
	lru := LRUCache{
		cap:    capacity,
		caches: map[int]*Node{},
		left:   &Node{},
		right:  &Node{},
	}
	lru.left.next = lru.right
	lru.right.prev = lru.left
	return lru
}
func (lru *LRUCache) remove(node *Node) {
	prev, next := node.prev, node.next
	prev.next = next
	next.prev = prev
}
func (lru *LRUCache) insert(node *Node) {
	prevRight := lru.right.prev
	prevRight.next = node
	lru.right.prev = node
	node.next = lru.right
	node.prev = prevRight
}
func (lru *LRUCache) Get(key int) int {
	if node, exists := lru.caches[key]; exists {
		lru.remove(node)
		lru.insert(node)
		return node.val
	}
	return -1
}
func (lru *LRUCache) Put(key, val int) {
	if node, exists := lru.caches[key]; exists {
		lru.remove(node)
		node.val = val
		lru.insert(node)
		return
	}
	if len(lru.caches) == lru.cap {
		node := lru.left.next
		lru.remove(node)
		delete(lru.caches, node.key)
	}
	node := &Node{
		key: key,
		val: val,
	}
	lru.insert(node)
	lru.caches[key] = node
}
